<?php

/* @autogenerated */
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Features\OAuth\Client\Domain\ClientData;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\AuthenticationRequest;

final class AuthenticationRequestUnitTest extends TestCase
{
    public function test_stores_required_properties(): void
    {
        $client = new ClientData('client-1', ['authorization_code'], true);
        $req = new AuthenticationRequest($client, 'openid profile', 'https://app.example/cb');

        $this->assertSame($client, $req->client);
        $this->assertSame('openid profile', $req->scope);
        $this->assertSame('https://app.example/cb', $req->redirect);
        $this->assertNull($req->responseType);
        $this->assertSame([], $req->audiences);
    }

    public function test_stores_optional_properties(): void
    {
        $client = new ClientData('c', ['code'], false);
        $req = new AuthenticationRequest($client, 'openid', 'https://cb', 'code', ['api', 'c']);

        $this->assertSame('code', $req->responseType);
        $this->assertSame(['api', 'c'], $req->audiences);
    }
}
